      label.textContent = "加入纸上草稿";
      input.value = "";
    }
  }
  function backToStart() {
    stopPolling();
    stopReading();
    mapTree = null;
    mapHero = null;
    mapNarrow = null;
    try { window.localStorage.removeItem(STORAGE_KEY); } catch (e) {}
    showPage("start");
    document.dispatchEvent(new CustomEvent("blackout:restart"));
  }
  function init() {
    el("copyBtn").addEventListener("click", copyMarkdown);
    el("restartBtn").addEventListener("click", backToStart);
    el("stopReadingBtn").addEventListener("click", stopReading);
    el("sketchInput").addEventListener("change", function () {
